<?php declare(strict_types=1);namespace App\Controllers\Admin;use App\Core\DB;use App\Core\Request;use App\Core\Response;use App\Models\AuditLog;use App\Models\Invoice;use App\Models\License;use App\Models\Order;use App\Services\InvoiceService;use App\Services\LicenseService;use App\Services\OrderService;final class OrderController extends AdminController{public function index(Request $c):Response{$h=Order::query()->select('t.*, u.email AS user_email, p.slug AS plan_slug')->join('JOIN '.DB::q(DB::table('users')).' u ON u.id = t.user_id')->join('JOIN '.DB::q(DB::table('plans')).' p ON p.id = t.plan_id')->orderBy('t.id','DESC');if($c->str('status')){$h->where('t.status',$c->str('status'));}$h->search(['u.email','t.payment_ref','t.coupon_code'],$c->str('q'));$k=$h->paginate($this->pageNumber($c),25);$k['items']=Order::castAll($k['items']);return $this->view('admin/orders/index',['res'=>$k,'filters'=>['q'=>$c->str('q'),'status'=>$c->str('status')],'meta'=>['title'=>t('admin.orders')]]);}public function show(Request $e,string $W):Response{$Y=Order::withRelations((int)$W);if(!$Y){return $this->redirect('/admin/orders');}return $this->view('admin/orders/show',['order'=>$Y,'invoice'=>Invoice::forOrder((int)$Y['id']),'license'=>$Y['license_id']?License::find((int)$Y['license_id']):null,'meta'=>['title'=>t('admin.order').' #'.$Y['id']]]);}public function action(Request $o,string $e):Response{$y=Order::find((int)$e);if(!$y){return $this->redirect('/admin/orders');}$i=$o->str('action');if($i==='mark_paid'&&$y['status']!=='paid'){OrderService::markPaid($y,'manual',$o->str('reference')?:'manual');}elseif($i==='refund'&&$y['status']==='paid'){Order::update((int)$y['id'],['status'=>'refunded']);if($y['license_id']){LicenseService::setStatus(License::find((int)$y['license_id']),'suspended','refund');}}elseif($i==='cancel'&&in_array($y['status'],['pending','awaiting_transfer'],true)){Order::update((int)$y['id'],['status'=>'cancelled']);}AuditLog::log('admin.order_'.$i,(string)$y['id']);$this->flash('success',t('common.saved'));return $this->redirect('/admin/orders/'.$e);}public function invoices(Request $C):Response{$o=Invoice::query()->select('t.*, u.email AS user_email')->join('JOIN '.DB::q(DB::table('users')).' u ON u.id = t.user_id')->orderBy('t.id','DESC');$o->search(['t.number','u.email'],$C->str('q'));$W=$o->paginate($this->pageNumber($C),25);$W['items']=Invoice::castAll($W['items']);$U=DB::fetch('SELECT COALESCE(SUM(total),0) AS total, COALESCE(SUM(tax),0) AS tax, COUNT(*) AS n FROM {{invoices}} WHERE issued_at >= ?',[gmdate('Y-01-01 00:00:00')]);return $this->view('admin/invoices',['res'=>$W,'q'=>$C->str('q'),'totals'=>$U,'meta'=>['title'=>t('admin.invoices')]]);}public function invoicePdf(Request $K,string $a):Response{$z=Invoice::find((int)$a);if(!$z){return $this->redirect('/admin/invoices');}return Response::raw(InvoiceService::pdf($z),'application/pdf')->withHeader('Content-Disposition','inline; filename="'.$z['number'].'.pdf"');}}